package com.modelrag.agent.controller;
import com.modelrag.agent.memory.LongTermMemoryService; import com.modelrag.common.dto.ApiResponse; import com.modelrag.common.exception.BusinessException; import com.modelrag.common.exception.ErrorCode; import com.modelrag.common.security.AccessControlService; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/memories") public class MemoryController {private final LongTermMemoryService memory;private final AccessControlService access;public MemoryController(LongTermMemoryService memory,AccessControlService access){this.memory=memory;this.access=access;}@PostMapping public ApiResponse<Void> upsert(@RequestBody LongTermMemoryService.Memory item){access.requireRole("ADMIN");memory.upsert(item);return ApiResponse.success(null);}@GetMapping public ApiResponse<List<LongTermMemoryService.Memory>> retrieve(@RequestParam String userId,@RequestParam String query,@RequestParam(defaultValue="5") int topK){var user=access.currentUser();if(!user.roles().contains("ADMIN")&&!user.id().equals(userId))throw new BusinessException(ErrorCode.FORBIDDEN,"只能查看自己的长期记忆");return ApiResponse.success(memory.retrieveRelevant(userId,query,topK));}}
